DELETE checks.*, checks.bdka, checks.numw
FROM checks
WHERE (((checks.bdka)=True) And ((checks.numw)=Forms!customers!numw));

DELETE checks.bdka, checks.numw
FROM checks
WHERE (((checks.bdka)=True) And ((checks.numw)=Forms!cust_checks!numw));

DELETE items_sales.*, items_sales.numw
FROM items_sales
WHERE (((items_sales.numw)=[Forms]![person_orders_list]![rnum]));

DELETE items_sales.item_name1, items_sales.item_name2, items_sales.item_name3, items_sales.item_name4, items_sales.item_name5, items_sales.*, items_sales.item_name6, items_sales.item_name21, items_sales.item_name22, items_sales.item_name23, items_sales.item_name24, items_sales.item_name25, items_sales.item_name26
FROM items_sales
WHERE (((items_sales.item_name1) Is Null) AND ((items_sales.item_name2) Is Null) AND ((items_sales.item_name3) Is Null) AND ((items_sales.item_name4) Is Null) AND ((items_sales.item_name5) Is Null) AND ((items_sales.item_name6) Is Null) AND ((items_sales.item_name21) Is Null) AND ((items_sales.item_name22) Is Null) AND ((items_sales.item_name23) Is Null) AND ((items_sales.item_name24) Is Null) AND ((items_sales.item_name25) Is Null) AND ((items_sales.item_name26) Is Null));

DELETE cust_list.*, IIf(nz([cust_list]![cdate])>nz([cust_list]![chdate]),[cust_list]![cdate],[cust_list]![chdate]) AS rpdate
FROM cust_list
WHERE (((IIf(nz([cust_list]![cdate])>nz([cust_list]![chdate]),[cust_list]![cdate],[cust_list]![chdate])) Is Not Null And (IIf(nz([cust_list]![cdate])>nz([cust_list]![chdate]),[cust_list]![cdate],[cust_list]![chdate]))>=[Forms]![empty_tables]![fwdate] And (IIf(nz([cust_list]![cdate])>nz([cust_list]![chdate]),[cust_list]![cdate],[cust_list]![chdate]))<=[Forms]![empty_tables]![twdate]));

DELETE presence.*, presence.wdate AS Expr1
FROM presence
WHERE (((presence.wdate) Is Not Null And (presence.wdate)>=[Forms]![empty_tables]![fwdate] And (presence.wdate)<=[Forms]![empty_tables]![twdate]));

DELETE tb_q_checks.*, tb_q_checks.tdate
FROM tb_q_checks
WHERE (((tb_q_checks.tdate) Is Not Null And (tb_q_checks.tdate)>=[Forms]![empty_tables]![fwdate] And (tb_q_checks.tdate)<=[Forms]![empty_tables]![twdate]));

DELETE tb_date_list.*, tb_date_list.datew AS q1, nz([snif]) AS q2
FROM tb_date_list
WHERE (((tb_date_list.datew)>=Forms!Calendar_of_Attendance!fwdate And (tb_date_list.datew)<=Forms!Calendar_of_Attendance!twdate) And ((nz([snif]))=nz(Forms!Calendar_of_Attendance!qsnif)));

DELETE tb_hsapakim.*, tb_hsapakim.hdate
FROM tb_hsapakim
WHERE (((tb_hsapakim.hdate) Is Not Null And (tb_hsapakim.hdate)>=[Forms]![empty_tables]![fwdate] And (tb_hsapakim.hdate)<=[Forms]![empty_tables]![twdate]));

DELETE items_sales.*, Val(nz([qtyp])) AS q, items_sales.wdate
FROM items_sales
WHERE (((Val(nz([qtyp])))>0) And ((items_sales.wdate) Is Not Null And (items_sales.wdate)>=Forms!empty_tables!fwdate And (items_sales.wdate)<=Forms!empty_tables!twdate));

DELETE orders.*, orders.odate
FROM orders
WHERE (((orders.odate) Is Not Null And (orders.odate)>=[Forms]![empty_tables]![fwdate] And (orders.odate)<=[Forms]![empty_tables]![twdate]));

DELETE tb_graf.*, tb_graf.qnumpr, tb_graf.qnumpl, tb_graf.sw
FROM tb_graf
WHERE (((tb_graf.qnumpr) Is Null) AND ((tb_graf.qnumpl) Is Null) AND ((tb_graf.sw)=True));
